test("+ は隙間の中央に左側の色で足す", () => {
  const gradient = gradientOf([
    { color: "#000000", ratio: 0 },
    { color: "#ffffff", ratio: 1 },
  ]);

  expect(GradientToken.addStop(gradient).stops).toEqual([
    { color: "#000000", ratio: 0 },
    { color: "#000000", ratio: 0.5 },
    { color: "#ffffff", ratio: 1 },
  ]);
});

test("+ は同じ広さの隙間が並ぶと配列で左の隙間に足す", () => {
  expect(
    GradientToken.addStop(gradientOfRatios([0, 0.5, 1])).stops.map(
      (stop) => stop.ratio,
    ),
  ).toEqual([0, 0.25, 0.5, 1]);
});

test("+ は両端の空きを隙間に数えない", () => {
  expect(
    GradientToken.addStop(gradientOfRatios([0.4, 0.6])).stops.map(
      (stop) => stop.ratio,
    ),
  ).toEqual([0.4, 0.5, 0.6]);
});

test("+ は浮動小数の誤差で広さを取り違えない", () => {
  // 0.3 - 0.1 と 0.5 - 0.3 は丸めないと別の広さになる
  expect(
    GradientToken.addStop(gradientOfRatios([0.1, 0.3, 0.5])).stops.map(
      (stop) => stop.ratio,
    ),
  ).toEqual([0.1, 0.2, 0.3, 0.5]);
});

test("+ は逆向きに並んだ 2 件の隙間も差の大きさで広さを測る", () => {
  expect(
    GradientToken.addStop(gradientOfRatios([0.9, 0.1, 0.2])).stops.map(
      (stop) => stop.ratio,
    ),
  ).toEqual([0.9, 0.5, 0.1, 0.2]);
});

test("+ は 1 件の比率がちょうど 0.5 なら同じ色を始点に足す", () => {
  const gradient = gradientOf([{ color: "#123456", ratio: 0.5 }]);

  expect(GradientToken.addStop(gradient).stops).toEqual([
    { color: "#123456", ratio: 0 },
    { color: "#123456", ratio: 0.5 },
  ]);
});

test("+ は色の変わり目が無いと角度を保って既定の 2 件を入れる", () => {
  const gradient: GradientToken = { shape: "linear", angle: 45, stops: [] };

  expect(GradientToken.addStop(gradient)).toEqual({
    shape: "linear",
    angle: 45,
    stops: GradientToken.Initial.stops,
  });
});

test("6 桁を超える比率の色の変わり目に欄の値のまま確定しても並びは変わらない", () => {
  const gradient = gradientOfRatios([0.12345678, 0.05]);
  const shown = GradientStop.ratioPercentOf(gradient.stops[0]);

  const edited = GradientToken.withStopRatioPercent(gradient, {
    stopIndex: 0,
    percent: shown,
  });

  expect(Option.unwrap(edited).stops.map((stop) => stop.color)).toEqual([
    "#000000",
    "#000001",
  ]);
});

test("比率が同じになった色の変わり目同士は元の並びを保つ", () => {
  const gradient = gradientOf([
    { color: "#ffffff", ratio: 0.3 },
    { color: "#000000", ratio: 0.5 },
    { color: "#888888", ratio: 1 },
  ]);

  const edited = GradientToken.withStopRatioPercent(gradient, {
    stopIndex: 2,
    percent: 30,
  });

  expect(Option.unwrap(edited).stops.map((stop) => stop.color)).toEqual([
    "#ffffff",
    "#888888",
    "#000000",
  ]);
});

test("2 件しか無いと色の変わり目を除けない", () => {
  expect(GradientToken.removeStop(gradientOfRatios([0, 1]), 0)).toEqual(
    Option.none,
  );
});

test("2 件目の stop の hex に打った 6 桁でその stop の色だけが変わる", () => {
  const field = stopFieldOf(
    gradientOf(gradientSelectionOf({ stops: ThreeStops })),
    "stop 2 の hex",
  );

  expect(TokenControl.valueFrom(field.target, "#00FF00")).toEqual(
    Option.some({
      kind: "gradients",
      value: {
        shape: "linear",
        angle: 90,
        stops: [
          { color: "#000000", ratio: 0 },
          { color: "#00ff00", ratio: 0.5 },
          { color: "#ffffff", ratio: 1 },
        ],
      },
    }),
  );
});

test("2 件目の stop の比率の欄に打った値はその stop の比率になる", () => {
  const field = stopFieldOf(
    gradientOf(gradientSelectionOf({ stops: ThreeStops })),
    "stop 2 の比率",
  );

  expect(TokenControl.valueFrom(field.target, "25")).toEqual(
    Option.some({
      kind: "gradients",
      value: {
        shape: "linear",
        angle: 90,
        stops: [
          { color: "#000000", ratio: 0 },
          { color: "#888888", ratio: 0.25 },
          { color: "#ffffff", ratio: 1 },
        ],
      },
    }),
  );
});

test("stop の hex に打った 6 桁でその stop の色だけが変わり、不透明度は残る", () => {
  const field = stopFieldOf(
    gradientOf(
      gradientSelectionOf({
        stops: [
          { color: "#00000080", ratio: 0 },
          { color: "#ffffff", ratio: 1 },
        ],
      }),
    ),
    "stop 1 の hex",
  );

  expect(TokenControl.valueFrom(field.target, "#FF0000")).toEqual(
    Option.some({
      kind: "gradients",
      value: {
        shape: "linear",
        angle: 90,
        stops: [
          { color: "#ff000080", ratio: 0 },
          { color: "#ffffff", ratio: 1 },
        ],
      },
    }),
  );
});

test("範囲外の比率は欄にそのまま出し、つまみはバーの端に寄せる", () => {
  const gradient = gradientOf(
    gradientSelectionOf({
      stops: [
        { color: "#000000", ratio: 0 },
        { color: "#ffffff", ratio: 1.5 },
      ],
    }),
  );

  expect(stopFieldOf(gradient, "stop 2 の比率").input).toEqual({
    kind: "percent",
    value: 150,
  });
  expect(gradient.knobs.map((knob) => knob.percent)).toEqual([0, 100]);
});

test("stop が 2 件なら どの行も − で消せない", () => {
  const gradient = gradientOf(gradientSelectionOf({ stops: TwoStops }));

  expect(gradient.stops.map((row) => row.afterRemove)).toEqual([
    Option.none,
    Option.none,
  ]);
});

test("ピッカーを開いて動かした 2 回目以降は続きとして届く", () => {
  const onSetTokenValue = renderGradient(TwoStops);
  const picker = screen.getByLabelText("stop 1 の色");

  fireEvent.click(picker);
  fireEvent.change(picker, { target: { value: "#ff0000" } });
  fireEvent.change(picker, { target: { value: "#00ff00" } });

  expect(
    onSetTokenValue.mock.calls.map(([, continuity]) => continuity),
  ).toEqual([EditContinuities.Separate, EditContinuities.Continued]);
});

test("ピッカーで動かしたあと別の欄へ移り、開き直さずに動かすと別のまとまりとして届く", () => {
  const onSetTokenValue = renderGradient(TwoStops);
  const picker = screen.getByLabelText("stop 1 の色");

  fireEvent.click(picker);
  fireEvent.change(picker, { target: { value: "#ff0000" } });
  fireEvent.blur(picker);
  fireEvent.focus(screen.getByLabelText("角度"));
  fireEvent.change(picker, { target: { value: "#00ff00" } });

  expect(
    onSetTokenValue.mock.calls.map(([, continuity]) => continuity),
  ).toEqual([EditContinuities.Separate, EditContinuities.Separate]);
});

test("続きとして送った値は 1 回の Undo で最初の値まで戻る", () => {
  const edited = sendColors(setupSelected(), [
    { color: "#ff0000", continuity: EditContinuities.Separate },
    { color: "#00ff00", continuity: EditContinuities.Continued },
  ]);

  const undone = Option.unwrap(EditorState.undo(edited));

  expect(primaryOf(undone)).toEqual(Option.some("#000000"));
});

test("ピッカーを開いて 2 回動かしても Ctrl+Z 1 回で元の色へ戻る", async () => {
  await addGradient();
  const picker = field("stop 1 の色");

  fireEvent.click(picker);
  fireEvent.change(picker, { target: { value: "#ff0000" } });
  fireEvent.change(picker, { target: { value: "#00ff00" } });
  expect(field("stop 1 の色")).toHaveProperty("value", "#00ff00");

  await userEvent.keyboard("{Control>}z{/Control}");

  expect(field("stop 1 の色")).toHaveProperty("value", "#000000");
});

test("色のトークンのピッカーを開いて 2 回動かしても Ctrl+Z 1 回で元の色へ戻る", async () => {
  await renderTokensView();
  await selectRow("primary");

  fireEvent.click(field("値"));
  fireEvent.change(field("値"), { target: { value: "#ff0000" } });
  fireEvent.change(field("値"), { target: { value: "#00ff00" } });
  expect(field("値")).toHaveProperty("value", "#00ff00");

  await userEvent.keyboard("{Control>}z{/Control}");

  expect(field("値")).toHaveProperty("value", "#3b82f6");
});

test("stop を追加すると 3 件になり、Ctrl+Z 1 回で 2 件へ戻る", async () => {
  await addGradient();

  await userEvent.click(
    within(propertyPane()).getByRole("button", { name: "stop を追加" }),
  );
  // 足せたことを先に見る。足せていないと Ctrl+Z が no-op でも最後の assert が通る。
  expect(row(/^gradient 90° · 3 stops$/)).toBeDefined();
  blurActive();

  await userEvent.keyboard("{Control>}z{/Control}");

  expect(row(/^gradient 90° · 2 stops$/)).toBeDefined();
});

test("作ったグラデーションは Background の欄の gradients の節から選べ、Used by に出る", async () => {
  await addGradient();
  await userEvent.click(
    within(leftPane()).getByRole("button", { name: "Layers" }),
  );
  await userEvent.click(
    within(leftPane()).getByRole("button", { name: "home-body" }),
  );

  await userEvent.selectOptions(
    within(propertyPane()).getByRole("combobox", { name: "Background" }),
    within(propertyPane()).getByRole("option", { name: "gradient" }),
  );
  await userEvent.click(
    within(leftPane()).getByRole("button", { name: "Tokens" }),
  );
  await openSection("gradients");
  await userEvent.click(row(/^gradient 90°/));

  expect(
    within(
      within(propertyPane()).getByRole("region", { name: "Used by" }),
    ).getByText("home-body.background"),
  ).toBeDefined();
});

test("sortBy では同じ値の要素が元の並びの順を保つ", () => {
  const items = [
    { name: "a", order: 2 },
    { name: "b", order: 1 },
    { name: "c", order: 2 },
    { name: "d", order: 1 },
  ];

  expect(
    ArrayEx.sortBy(items, (item) => item.order).map((item) => item.name),
  ).toEqual(["b", "d", "a", "c"]);
});
